local KTool = CS.Engine.Lib.KTool

--- from:  > name: DailyCustomerPanel
---@class MaidCoffeeDailyEventController
---@field Env                           	MaidCoffeeDailyEventController          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Cell3                         	UnityEngine.RectTransform               
---@field Cell2                         	UnityEngine.RectTransform               
---@field Cell1                         	Engine.Modules.LuaBehaviour             
---@field SymbolNode                    	UnityEngine.RectTransform               
---@field TextNumber                    	UnityEngine.RectTransform               
local MaidCoffeeDailyEventController = Class('MaidCoffeeDailyEventController')
local CellCount = 3
function MaidCoffeeDailyEventController:__init()

end

function MaidCoffeeDailyEventController:__delete()
    self.headEnv = nil
end

function MaidCoffeeDailyEventController:Awake()
    self:InitCellEnv()
end

function MaidCoffeeDailyEventController:InitCellEnv()
    self.headEnv = {}
    for i = 1, CellCount do
        local cell = self["Cell"..i]
        if cell then
            local env = CfUtils.GetLuaScr(cell,"Game.MaidCoffee.MaidCoffeeGuestUIDialog.Cell.MaidCoffeeGuestHeadNodeCell")
            if not isNull(env) then
               self.headEnv[i] = env
            end
        end
    end

    local env = CfUtils.GetLuaScr(self.CellMerchant.gameObject,"Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManageBusinessNode")
    if env then
        self.businessEnv = env
    end
end

function MaidCoffeeDailyEventController:RefreshShow()
    local isCustomerUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3016)
    KTool.SetActive(self.controller.gameObject,true)
    CfUtils.SetActive(self.CustomerNumber.gameObject,isCustomerUnLock)
    if isCustomerUnLock then
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local maidHomeDoJo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
        if maidHomeDoJo then
            local num = maidHomeDoJo:GetEventCompletedNum() or 0
            local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
            local maxNum = MaidCoffeeUtils.GetMaidCoffeeEventMaxNum()
            local status = maxNum == num and 1 or 2
            CfUtils.SetUISwitchText(self.TextNumber,status)
            KTool.SetActive(self.SymbolNode,maxNum == num)
            CfUtils.FillText(self.TextNumber,string.format("%s/%s",maxNum - num,maxNum))
        end
        self:RefreshHeadShow()
    else
        for i = 1, #self.headEnv do
            KTool.SetActive(self.headEnv[i].controller.gameObject,false)
        end
    end
    ---刷新商人显示
    self:RefreshBusinessNodeShow()
end

function MaidCoffeeDailyEventController:RefreshBusinessNodeShow()
    local isCallOnUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id266)
    if not isCallOnUnLock then
        KTool.SetActive(self.CellMerchant.gameObject,false)
        return
    end
    KTool.SetActive(self.CellMerchant.gameObject,true)
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetMerchantData()
    if not isNull(data) then
        self.businessEnv:RefreshShow(data)
    end
end

function MaidCoffeeDailyEventController:RefreshHeadShow()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local events = maidCoffeeComponent:GetAllEvents()
    for i = 1, #self.headEnv do
        local data = events[i]
        if not isNull(data) then
            self.headEnv[i]:RefreshHeadShow(data)
            KTool.SetActive(self.headEnv[i].controller.gameObject,true)
        else
            KTool.SetActive(self.headEnv[i].controller.gameObject,false)
        end
    end
end

function MaidCoffeeDailyEventController:OnDestroy()
    self.businessEnv:Delete()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return MaidCoffeeDailyEventController